import assert from 'node:assert/strict';
import { readFile,writeFile,mkdir,readdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
const root=new URL('../',import.meta.url);
const code=await readFile(new URL('dist/onchain-worker/onchain-worker.js',root),'utf8');
const map=JSON.parse(await readFile(new URL('dist/onchain-worker/onchain-worker.js.map',root),'utf8'));
const allowed=['src/errors.mjs','src/responses.mjs','src/onchain/input.mjs','src/onchain/rpc.mjs','src/onchain/verify.mjs','src/onchain/http.mjs','deploy/onchain-worker.mjs'];
assert(map.sources.every(path=>allowed.some(a=>path.replaceAll('\\','/').endsWith(a))),'Unexpected source in Worker upload');
assert.equal(map.sources.length,allowed.length);
assert(!/local-competitor-audit|PREVIOUS_WINNER_AUDIT|ASYMMETRIC_STRATEGY|register-wasm|PRIVATE_KEY|gh[pousr]_[A-Za-z0-9]{20}/.test(code),'Private material or signing tool was bundled');
assert(!map.sources.some(x=>/research\/|reports\/|STRATEGY\.md|MEMORY\.md|AGENTS\.md/.test(x)),'Research or local state was bundled');
const assetDirectory=new URL('deploy/onchain-public/',root),assets=(await readdir(assetDirectory)).sort();assert.deepEqual(assets,['miner.yaml'],'Unexpected public asset set');
const yaml=await readFile(new URL('miner.yaml',assetDirectory));
const descriptor=JSON.parse(yaml.toString('utf8'));
assert.deepEqual(descriptor.semantics.supported_intents,['CRYPTO_TRANSFER_VERIFY','ONCHAIN_METRIC_VERIFY']);
assert(descriptor.base_url.startsWith('https://'),'Public descriptor needs HTTPS');
assert(!/local-competitor-audit|PREVIOUS_WINNER_AUDIT|ASYMMETRIC_STRATEGY/.test(yaml.toString('utf8')),'Private data in descriptor');
const report={checked_at:new Date().toISOString(),bytes:Buffer.byteLength(code),sha256:createHash('sha256').update(code).digest('hex'),bundled_sources:map.sources,public_assets:assets,yaml_bytes:yaml.length,yaml_sha256:'0x'+createHash('sha256').update(yaml).digest('hex'),source_boundary_passed:true,signing_code_absent:true,scope:'Local dry-run package only; no upload or production CPU claim'};
await mkdir(new URL('reports/onchain-miner/',root),{recursive:true});await writeFile(new URL('reports/onchain-miner/bundle-audit.json',root),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));
